"""Typed payload models for the offline evidence pipeline.

The models mirror the historical H3Act frame spelling (``Type``,
``data_to_transfered``, ``End_Stream``, ``Time_to_Stop``) but carry *compiled*
template results: every header name/value and every data payload is a
:class:`modules.byte_program.Node`, so compressed expressions survive typing
without ever being expanded.

Two families live here:

``Raw*`` models re-check the JSON shape with strict pydantic rules (no
coercion, no unknown member, exactly one header representation).  The compiled
models are what :class:`modules.fuzz_adapter.FuzzExecutor` replays.
"""
from typing import Dict, List, Optional, Tuple, Union

from pydantic import (BaseModel, ConfigDict, Field, ValidationError,
                      model_validator)

from modules.byte_program import MAX, Node


class StrictModel(BaseModel):
    """No coercion, no unknown keys: the documented input contract."""
    model_config = ConfigDict(extra='forbid', strict=True)


class NodeModel(BaseModel):
    """Compiled payload carrier (byte nodes are opaque to pydantic)."""
    model_config = ConfigDict(arbitrary_types_allowed=True, extra='forbid',
                              strict=True)


class RawHeaderFrame(StrictModel):
    Type: str
    headers_kv: Optional[Dict[str, str]] = None
    data_to_transfered: Optional[List[List[str]]] = None
    End_Stream: bool = False

    @model_validator(mode='after')
    def exactly_one_representation(self):
        if (self.headers_kv is None) == (self.data_to_transfered is None):
            raise ValueError('headers need exactly one of headers_kv/data_to_transfered')
        return self


class RawDataFrame(StrictModel):
    Type: str
    data_to_transfered: str
    End_Stream: bool = True


class RawSleepFrame(StrictModel):
    Type: str
    Time_to_Stop: int

    @model_validator(mode='after')
    def in_range(self):
        if not 0 <= self.Time_to_Stop <= MAX:
            raise ValueError('pause range')
        return self


RAW_FRAMES = {'headers': RawHeaderFrame, 'data': RawDataFrame,
              'datagram': RawDataFrame, 'sleep': RawSleepFrame}


class H3HeaderFrame(NodeModel):
    Type: str = 'headers'
    #: compiled ``(name, value)`` pairs in JSON member order
    data_to_transfered: List[Tuple[Node, Node]] = Field(default_factory=list)
    End_Stream: bool = False


class H3DataFrame(NodeModel):
    Type: str = 'data'
    #: compiled payload node
    data_to_transfered: Node
    End_Stream: bool = True


class H3SleepFrame(NodeModel):
    Type: str = 'sleep'
    Time_to_Stop: int = 0
    End_Stream: bool = False


class Expect(BaseModel):
    """Supplied intended routing identity of one case."""
    model_config = ConfigDict(extra='forbid', strict=True, frozen=True)
    method: bytes
    target: bytes
    host: bytes
    host_folded: bytes


class Case(BaseModel):
    model_config = ConfigDict(extra='forbid', strict=True, frozen=True)
    name: str
    stream: int
    expect: Expect


class FuzzingPayload(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True, extra='forbid')
    test_cases: Dict[str, List[Union[H3HeaderFrame, H3DataFrame, H3SleepFrame]]]
    cases: List[Case] = Field(default_factory=list)


COMPILED = {'headers': H3HeaderFrame, 'data': H3DataFrame,
            'datagram': H3DataFrame, 'sleep': H3SleepFrame}


def validate_frame(raw):
    """Strictly re-type one raw frame dict; raises ValueError when invalid."""
    if type(raw) is not dict:
        raise ValueError('frame object')
    kind = raw.get('Type')
    if type(kind) is not str:
        raise ValueError('frame Type')
    model = RAW_FRAMES.get(kind)
    if model is None:
        raise ValueError('frame Type')
    try:
        return model.model_validate(raw)
    except ValidationError as exc:
        raise ValueError('frame %s' % kind) from exc


def header_pairs(raw_frame):
    """Ordered ``(name, value)`` source strings of a validated header frame."""
    if raw_frame.headers_kv is not None:
        return list(raw_frame.headers_kv.items())
    return [(pair[0], pair[1]) for pair in raw_frame.data_to_transfered]


def compile_frames(raw_frames, context, coordinate):
    """Compile every template of one case's frames into typed payload models."""
    compiled = []
    for index, raw in enumerate(raw_frames):
        checked = validate_frame(raw)
        base = '%s/frame/%d' % (coordinate, index)
        if checked.Type == 'sleep':
            compiled.append(H3SleepFrame(Time_to_Stop=checked.Time_to_Stop))
            continue
        if checked.Type == 'headers':
            pairs = []
            for pair_index, (name, value) in enumerate(header_pairs(checked)):
                pairs.append((
                    context.template(name, '%s/h/%d/n' % (base, pair_index)),
                    context.template(value, '%s/h/%d/v' % (base, pair_index)),
                ))
            compiled.append(H3HeaderFrame(data_to_transfered=pairs,
                                          End_Stream=checked.End_Stream))
        else:
            payload = context.template(checked.data_to_transfered,
                                       '%s/data' % base)
            compiled.append(COMPILED[checked.Type](
                Type=checked.Type, data_to_transfered=payload,
                End_Stream=checked.End_Stream))
    return compiled


def compile_cases(cases, context):
    """Build the typed :class:`FuzzingPayload` for the whole document."""
    data = {}
    records = []
    for index, case in enumerate(cases):
        name = case['name']
        expect = case['expect']
        data[name] = compile_frames(case['frames'], context, 'case/%d' % index)
        records.append(Case(name=name, stream=4 * index, expect=Expect(
            method=expect['method'].encode('ascii'),
            target=expect['target'].encode('ascii'),
            host=expect['host'].encode('ascii'),
            host_folded=expect['host'].encode('ascii').lower())))
    return FuzzingPayload(test_cases=data, cases=records)
