"""Decoded event records consumed by HttpClient in offline mode."""
from dataclasses import dataclass, field


class SendError(Exception):
    """A frame was offered after the request send side had ended."""


@dataclass
class HeadersReceived:
    stream_id: int
    headers: list
    stream_ended: bool


@dataclass
class DataReceived:
    stream_id: int
    data: object
    stream_ended: bool


@dataclass
class ConnectionTerminated:
    error_code: int = 0
    reason_phrase: str = 'capture close'


@dataclass
class ExternalEvent:
    """One decoded entry of the document's ``events`` tape."""
    at: int
    kind: str
    stream: int = 0
    fields: list = field(default_factory=list)
    data: object = None
    end: bool = False

    def decoded(self):
        if self.kind == 'headers':
            return HeadersReceived(self.stream, self.fields, self.end)
        if self.kind == 'data':
            return DataReceived(self.stream, self.data, self.end)
        return ConnectionTerminated()
